def create_first_versions(apps, schema_editor):
    """Las plantillas que ya existían arrancan su historial con su estado
    actual como versión 1, fechada cuando se modificó por última vez."""
    LabelTemplate = apps.get_model("labels", "LabelTemplate")
    LabelTemplateVersion = apps.get_model("labels", "LabelTemplateVersion")
    for template in LabelTemplate.objects.all():
        version = LabelTemplateVersion.objects.create(
            template=template,
            number=1,
            name=template.name,
            width_cm=template.width_cm,
            height_cm=template.height_cm,
            design=template.design or {},
            created_by_id=template.owner_id,
        )
        LabelTemplateVersion.objects.filter(pk=version.pk).update(created_at=template.updated_at)


